{

    float angle = sin(iTime)*180.0; // idk what happened but > 180 not worked
    angle = (angle-45.0)*2.0;
    vec2 uv = fragCoord/iResolution.xy;  
    float rad = angle*(3.141596/180.0);//abs(sin(iTime))*6.28;

    //linecalculate
    float line = (((uv.x-0.5)*cos(rad)+0.5));

    //shift calculate
    float shift = sin(iTime)*0.1;

    if (uv.y>line){
    uv+=shift;}
    else{uv-=shift;}
    fragColor = texture(iChannel0,uv);


}
